block('f9css','css',open('/workspace/feat/f9_css.css').read())
# Mega Hyper Rares: TCGdex scans are flat yellow placeholders (no etched art) -> prefer Scrydex scans (large for zoom, medium via srcset)
rep('function cardSrcs(s,localId,extra=[]){if(s.game==="lor")return lorSrcs(s,localId);const n=String(localId).replace(/^0+(?=\\d)/,"");const base=`https://assets.tcgdex.net/en/${s.serie}/${s.dex}/${localId}`;\n return [`${base}/high.webp`,',
    '/* TCGdex scans of these Mega Hyper Rares are flat yellow (etched art missing); Scrydex has real scans */\n/* (a hoisted function, not a const: cardSrcs already runs while the collection is hydrated earlier in this script) */\nfunction srcFix(d){return ({"me01":["187","188"],"me02":["130"],"me02.5":["294","295"],"me03":["124"],"me04":["122"],"me05":["120"]})[d]||[]}\nfunction cardSrcs(s,localId,extra=[]){if(s.game==="lor")return lorSrcs(s,localId);const n=String(localId).replace(/^0+(?=\\d)/,"");const base=`https://assets.tcgdex.net/en/${s.serie}/${s.dex}/${localId}`;\n const fx=s.ptcg&&srcFix(s.dex).includes(n)?[`https://images.scrydex.com/pokemon/${s.ptcg}-${n}/large`,`https://images.scrydex.com/pokemon/${s.ptcg}-${n}/medium`]:[];\n return [...fx,`${base}/high.webp`,')
rep('if(/_hires\\.png$/.test(u))return `srcset="${esc(u.replace(/_hires\\.png$/,".png"))} 245w, ${esc(u)} 734w"`+sz;return ""}',
    'if(/_hires\\.png$/.test(u))return `srcset="${esc(u.replace(/_hires\\.png$/,".png"))} 245w, ${esc(u)} 734w"`+sz;if(/^https:\\/\\/images\\.scrydex\\.com\\/.+\\/large$/.test(u))return `srcset="${esc(u.replace(/large$/,"medium"))} 367w, ${esc(u)} 733w"`+sz;return ""}')
